#!/usr/bin/env python3
"""Generate tool version documentation from the packaged inventory."""
import argparse
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]

def render():
    data = json.loads((ROOT / 'rvw/src/rvw/doctor/tools.json').read_text())
    lines = ['# Tool versions and install policy', '',
             'Generated by `python3 scripts/generate-tool-docs.py`. Edit the inventory.', '',
             'Observed versions below come from prior recorded macOS ARM64 checks.',
             'They are not clean-install qualification. No complete pinned combination is',
             'qualified. Linux and clean macOS installs are NOT RUN in this change.',
             'Use `scripts/qualify-install.py` to record new install and runtime evidence.', '',
             '| Tool | Observed version | Source pin | Install flag | Qualification |',
             '|---|---|---|---|---|']
    for t in data['tools']:
        lines.append(f"| {t['name']} | {t['observed_version']} | {t['pin']} | `--with-{t['flag']}` | {t['version_evidence']} |")
    lines += ['', '## Python lock', '',
              '`scripts/install.sh` uses `uv sync --locked`. Development setup uses',
              '`uv sync --locked --extra dev --extra mcp --project rvw`.',
              'Update dependencies with `uv lock --project rvw` in a reviewed change.',
              'Optional cocotb, pyuvm and wellen extras are in the same lock.', '',
              '## Native version checks', '',
              'The installer refuses missing tools, versions below its minimum, JDK outside',
              'major 21 and gem5 outside 25.1.0.1 or without RISC-V support.',
              'Unknown versions fail. Versions outside the observed table warn.',
              'Verilator 5.049 has a known FSM coverage crash. Keep FSM coverage disabled.',
              'Host package versions can drift. Source pins do not make builds bit-for-bit',
              'reproducible. Presence and version probes do not test a tool flow.', '',
              'Linux recipes and native qualification remain open under #17. Complete',
              'reproducible combinations remain open under #40. Bundles remain under #71.', '']
    return '\n'.join(lines)

def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--check',action='store_true');args=parser.parse_args()
    target=ROOT/'docs/TOOL_VERSIONS.md';text=render()
    if args.check:
        return int(target.read_text()!=text)
    target.write_text(text);return 0
if __name__=='__main__':raise SystemExit(main())
